/**
 * One scenario per check of cash-seam-build-standard, for Roof Desk.
 *
 * Generated by `npx @aipathway/conformance init cash-seam-build-standard`, then
 * filled in. The runner delivers named events one at a time, as the job
 * system's webhooks and the ledger's schedule would, and runs the build once
 * per event. Every `holds` reads the world the runner owns: its records and
 * its `calls`, never the build.
 *
 * Roof Desk is the call hop. The quote, invoice and chase hops in build.mjs
 * are labelled stand-ins, there so the job id can be followed to the chase.
 *
 * Caller numbers are from ACMA's fictitious range (0491 570 xxx).
 */

import { CashSeamWorld } from "@aipathway/conformance";

const A = "+61491570161";
const B = "+61491570162";
const DAY = 24 * 60 * 60 * 1000;
const UNATTENDED = new Set(["webhook", "schedule", "poll"]);
const HOP_EVENT = { write_job: "call_received", draft_quote: "job_created", write_invoice: "job_completed" };

async function deliver(w, build, name, via, payload = {}) {
  const ev = w.makeEvent(name, via, payload);
  w.deliver(ev);
  await build(w.ports());
  w.settle();
  return ev;
}

/** Fire job_created for every job the job system has made since the last look. */
async function announce(w, build) {
  for (const j of w.unannouncedJobs()) await deliver(w, build, "job_created", "webhook", { jobId: j.id });
}

/** The whole path for each caller: call, job created, quote accepted, job completed, invoice overdue. */
async function chain(w, build, callers, { beforeCompletion } = {}) {
  for (const c of callers) await deliver(w, build, "call_received", "webhook", c);
  await announce(w, build);
  for (const s of w.sends.filter((x) => x.kind === "quote")) {
    if (w.accept(s.id)) {
      const q = w.quotes.find((x) => x.id === s.id);
      await deliver(w, build, "quote_accepted", "webhook", { quoteId: q.id, jobId: q.jobId });
    }
  }
  if (beforeCompletion) await beforeCompletion();
  for (const j of [...w.jobs]) {
    if (w.complete(j.id)) await deliver(w, build, "job_completed", "webhook", { jobId: j.id });
  }
  w.advance(16 * DAY);
  await deliver(w, build, "invoice_overdue", "schedule");
}

const sendCalls = (w) => w.calls.filter((c) => c.port === "issue_notice" || c.port === "send_sms");
const downstreamSearches = (w) =>
  w.calls.filter((c) => c.port === "read_job" && c.request?.search && w.eventById(c.request.event)?.name !== "call_received");
const ownerNames = (w) => new Set(Object.values(w.owners));

export const scenarios = [
  {
    checkId: "identity-from-the-system-of-record",
    // 1. Two open jobs, two customers with the same name; one is quoted, accepted and completed.
    world: () =>
      new CashSeamWorld({
        jobs: [
          { id: "JS-11", customerName: "D. Nguyen", phone: A, status: "open" },
          { id: "JS-12", customerName: "D. Nguyen", phone: B, status: "open" },
        ],
      }),
    drive: async (build, w) => {
      await deliver(w, build, "job_created", "webhook", { jobId: "JS-12" });
      const q = w.quotesFor("JS-12")[0];
      if (q && w.accept(q.id)) await deliver(w, build, "quote_accepted", "webhook", { quoteId: q.id, jobId: "JS-12" });
      w.complete("JS-12");
      await deliver(w, build, "job_completed", "webhook", { jobId: "JS-12" });
    },
    holds: (w) => {
      const issued = w.issuedIds();
      if (w.quotes.length !== 1 || w.invoices.length !== 1) return false;
      const [q] = w.quotes;
      const [i] = w.invoices;
      return (
        q.jobId === "JS-12" && q.status === "accepted" &&
        i.jobId === "JS-12" && i.quoteId === q.id &&
        issued.has(i.jobId) && issued.has(i.quoteId) &&
        w.invoicesFor("JS-11").length === 0 && w.quotesFor("JS-11").length === 0 &&
        downstreamSearches(w).length === 0
      );
    },
    describe: (w) => `quotes ${JSON.stringify(w.quotes.map((q) => [q.id, q.jobId]))}; invoices ${JSON.stringify(w.invoices.map((i) => [i.id, i.jobId, i.quoteId]))}; downstream searches ${downstreamSearches(w).length}`,
  },
  {
    checkId: "one-job-per-enquiry",
    // 2. The same number rings the after-hours line, then fills in the web form.
    world: () => new CashSeamWorld(),
    drive: async (build, w) => {
      await deliver(w, build, "call_received", "webhook", { phone: A, customerName: "D. Nguyen", door: "phone" });
      w.advance(12 * 60 * 1000);
      await deliver(w, build, "call_received", "webhook", { phone: A, customerName: "D. Nguyen", door: "web" });
    },
    holds: (w) => {
      const jobs = w.jobsFor(A);
      if (jobs.length !== 1 || w.enquiries.length !== 2) return false;
      const writes = w.calls.map((c, i) => [c, i]).filter(([c]) => c.port === "write_job");
      const readBeforeEach = writes.every(([, i]) => w.calls.slice(0, i).some((c) => c.port === "read_job" && c.request?.search?.phone === A));
      return writes.length === 2 && readBeforeEach && !w.enquiries[0].duplicateOf && w.enquiries[1].duplicateOf === jobs[0].id;
    },
    describe: (w) => `${w.jobsFor(A).length} job(s) for the number; enquiries ${JSON.stringify(w.enquiries)}`,
  },
  {
    checkId: "no-external-id-no-write",
    // 3. A null id on the quote write for the first job and on the invoice write for the second.
    world: () => new CashSeamWorld({ nullQuoteFor: ["JS-1001"], nullInvoiceFor: ["JS-1002"] }),
    drive: (build, w) => chain(w, build, [{ phone: A, customerName: "D. Nguyen" }, { phone: B, customerName: "R. Kaur" }]),
    holds: (w) => {
      if (w.jobs.length !== 2) return false;
      const esc = (ref, stage) => w.escalations.some((e) => e.ref === ref && e.stage === stage && e.reason === "write_failed" && ownerNames(w).has(e.owner));
      const issued = w.issuedIds();
      const firstTouched = w.quotesFor("JS-1001").length > 0 || w.invoicesFor("JS-1001").length > 0;
      const secondInvoiced = w.invoicesFor("JS-1002").length > 0 || w.sends.some((s) => s.kind === "invoice") || w.releases.some((r) => r.kind === "invoice");
      const noNullRefs = w.quotes.every((q) => q.jobId && issued.has(q.jobId)) && w.invoices.every((i) => i.jobId && issued.has(i.jobId));
      const sendsReal = w.sends.every((s) => s.id && issued.has(s.id));
      return esc("JS-1001", "quote") && esc("JS-1002", "invoice") && w.quotesFor("JS-1002").length === 1 && !firstTouched && !secondInvoiced && w.chases.length === 0 && noNullRefs && sendsReal;
    },
    describe: (w) => `escalations ${JSON.stringify(w.escalations.map((e) => [e.stage, e.ref, e.reason, e.owner]))}; invoices ${w.invoices.length}; chases ${w.chases.length}`,
  },
  {
    checkId: "the-chain-carries-the-id",
    // 4. One enquiry, the whole path.
    world: () => new CashSeamWorld(),
    drive: (build, w) => chain(w, build, [{ phone: A, customerName: "D. Nguyen" }]),
    holds: (w) => {
      if (w.jobs.length !== 1 || w.quotes.length !== 1 || w.invoices.length !== 1 || w.chases.length !== 1) return false;
      const [j] = w.jobs;
      const [q] = w.quotes;
      const [i] = w.invoices;
      const [ch] = w.chases;
      const chaseAt = w.calls.findIndex((c) => c.port === "send_sms" && c.request?.send === "chase");
      const seen = chaseAt > 0 && w.calls.slice(0, chaseAt).some((c) => c.port === "read_ledger" && c.request?.ledger && c.response?.ids?.includes(ch.invoiceId));
      return q.jobId === j.id && i.jobId === j.id && i.quoteId === q.id && ch.invoiceId === i.id && seen;
    },
    describe: (w) => `job ${w.jobs.map((j) => j.id)}; quote ${JSON.stringify(w.quotes.map((q) => [q.id, q.jobId]))}; invoice ${JSON.stringify(w.invoices.map((i) => [i.id, i.jobId, i.quoteId]))}; chase ${JSON.stringify(w.chases.map((c) => c.invoiceId))}`,
  },
  {
    checkId: "confirmation-is-not-a-write",
    // 5. The first job's quote write answers "Quote created" with an id, and stores nothing.
    world: () => new CashSeamWorld({ phantomQuoteFor: ["JS-1001"] }),
    drive: (build, w) => chain(w, build, [{ phone: A, customerName: "D. Nguyen" }, { phone: B, customerName: "R. Kaur" }]),
    holds: (w) => {
      const ghost = w.phantomIds[0];
      if (!ghost) return false;
      const ghostTouched = w.releases.some((r) => r.id === ghost) || w.sends.some((s) => s.id === ghost);
      const escalated = w.escalations.some((e) => e.ref === "JS-1001" && e.stage === "quote" && ownerNames(w).has(e.owner));
      const sends = sendCalls(w);
      const backed = sends.every((s) => {
        const before = w.calls.slice(0, w.calls.indexOf(s));
        const id = s.request.id;
        const readBack = before.some((c) => (c.port === "read_job" && c.request?.quote === id && c.response?.id === id) || (c.port === "read_ledger" && c.request?.invoice === id && c.response?.id === id));
        const released = before.some((c) => c.port === "gate" && c.request?.id === id && (c.request.person || c.request.rule));
        return readBack && released;
      });
      return !ghostTouched && escalated && sends.length === 3 && backed;
    },
    describe: (w) => `phantom ${JSON.stringify(w.phantomIds)}; sends ${JSON.stringify(w.sends.map((s) => [s.kind, s.id]))}; escalations ${JSON.stringify(w.escalations.map((e) => [e.stage, e.ref, e.reason]))}`,
  },
  {
    checkId: "named-unattended-trigger",
    // 6. The full chain as events, plus a chat message asking for an invoice.
    world: () => new CashSeamWorld(),
    drive: (build, w) =>
      chain(w, build, [{ phone: A, customerName: "D. Nguyen" }], {
        beforeCompletion: () => deliver(w, build, "chat_message", "chat", { text: "can you raise the invoice for the Nguyen roof now", jobId: "JS-1001" }),
      }),
    holds: (w) => {
      const writes = w.calls.filter((c) => c.port in HOP_EVENT && c.request && !("attach" in c.request));
      const chases = w.calls.filter((c) => c.port === "send_sms" && c.request?.send === "chase");
      if (writes.length !== 3 || chases.length !== 1) return false;
      const ok = writes.every((c) => {
        const ev = w.eventById(c.request.trigger);
        return ev && UNATTENDED.has(ev.via) && ev.name === HOP_EVENT[c.port];
      });
      const chaseEv = w.eventById(chases[0].request.trigger);
      const chatWoke = w.calls.some((c) => w.eventById(c.request?.trigger ?? c.request?.event)?.via === "chat");
      return ok && Boolean(chaseEv) && chaseEv.name === "invoice_overdue" && UNATTENDED.has(chaseEv.via) && !chatWoke;
    },
    describe: (w) => `writes ${JSON.stringify(w.calls.filter((c) => c.port in HOP_EVENT).map((c) => [c.port, w.eventById(c.request?.trigger)?.name ?? null]))}; chases ${w.chases.length}`,
  },
  {
    checkId: "exception-owner-travels",
    // 7. Two completed jobs: one already carries a person's open exception; the other's invoice write returns no id.
    world: () =>
      new CashSeamWorld({
        jobs: [
          { id: "JS-21", customerName: "D. Nguyen", phone: A, status: "complete", exception: { reason: "disputed scope: valley iron not in the quote", owner: "Priya Nair" } },
          { id: "JS-22", customerName: "R. Kaur", phone: B, status: "complete" },
        ],
        nullInvoiceFor: ["JS-22"],
      }),
    drive: async (build, w) => {
      await deliver(w, build, "job_completed", "webhook", { jobId: "JS-21" });
      await deliver(w, build, "job_completed", "webhook", { jobId: "JS-22" });
    },
    holds: (w) => {
      if (w.invoices.length !== 0) return false;
      const writesFor21 = w.calls.filter((c) => c.port === "write_invoice" && c.request?.jobId === "JS-21").length;
      const hold = w.escalations.some((e) => e.ref === "JS-21" && e.owner === "Priya Nair");
      const failed = w.escalations.some((e) => e.ref === "JS-22" && e.reason === "write_failed" && e.owner === w.owners.invoice);
      const allOwned = w.escalations.every((e) => e.owner && (ownerNames(w).has(e.owner) || e.owner === "Priya Nair"));
      return writesFor21 === 0 && hold && failed && allOwned && w.job("JS-21")?.exception?.owner === "Priya Nair";
    },
    describe: (w) => `escalations ${JSON.stringify(w.escalations.map((e) => [e.ref, e.reason, e.owner]))}; invoices ${w.invoices.length}`,
  },
  {
    checkId: "survives-the-builder",
    // 8. Not a software check. Declared in the node's README; never scored green on its own say-so.
    world: () => new CashSeamWorld(),
    drive: () => {},
    holds: () => false,
    describe: () => "declared, not run",
  },
];

// Runs only in production, against the business's own job system and ledger.
export const liveScenarios = [
  {
    checkId: "pass-test",
    // 9. Two calls from one number, acceptance, completion, overdue, then again with one null write.
    world: () => new CashSeamWorld(),
    drive: (build, w) => chain(w, build, [{ phone: A, customerName: "D. Nguyen" }, { phone: A, customerName: "D. Nguyen", door: "web" }]),
    holds: (w) => {
      const jobs = w.jobs?.length ?? 0;
      const quotes = w.quotes?.length ?? 0;
      const invoices = w.invoices?.length ?? 0;
      const chases = w.chases?.length ?? 0;
      return jobs === 1 && quotes === 1 && invoices === 1 && chases === 1 && w.invoices[0].quoteId === w.quotes[0].id && w.quotes[0].jobId === w.jobs[0].id;
    },
    describe: (w) => `${(w.calls ?? []).length} port call(s)`,
  },
];
